# Ordered so the most commonly used ones come first in the GUI dropdown.
COLORMAP_NAMES = ['gray', 'jet', 'hsv', 'hot', 'copper', 'blackbody', 'blue', 'blueblackred', 'bluehot', 'blueredgreen', 'copper_lab', 'cyan', 'cyanmagenta', 'geo', 'gold', 'green', 'landandsea', 'magenta', 'map', 'pastels', 'pastelsmap', 'planetearth', 'rainbow', 'red', 'redwhite', 'redwhiteblue', 'redwhitegreen', 'relief', 'spectrum', 'terrain', 'yellow', 'yellowhot']

_cache = {}


def get_lut(name, flip=False):
    """Return the (N,3) uint8 RGB lookup table for ``name``, reversed if
    ``flip``. Raises KeyError with the list of valid names if unknown."""
    if name not in _PACKED:
        raise KeyError(f'Unknown colormap {name!r}; available: {COLORMAP_NAMES}')
    if name not in _cache:
        n, blob = _PACKED[name]
        raw = zlib.decompress(base64.b64decode(blob))
        _cache[name] = np.frombuffer(raw, dtype=np.uint8).reshape(n, 3)
    lut = _cache[name]
    return lut[::-1].copy() if flip else lut
